package com.echovault.servlet;import com.echovault.dao.AdminDAO;import com.echovault.util.Flash;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.annotation.WebInitParam;import jakarta.servlet.http.*;import java.io.*;@WebServlet(urlPatterns="/admin-login",initParams={@WebInitParam(name="module",value="EchoVault Admin Authentication")}) public class AdminLoginServlet extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{try{int id=new AdminDAO().authenticate(q.getParameter("username"),q.getParameter("password"));if(id<0){Flash.set(q,"error","Invalid administrator credentials.");s.sendRedirect("admin-login.jsp");return;}HttpSession h=q.getSession(true);h.setAttribute("adminId",id);h.setAttribute("adminName",q.getParameter("username"));s.sendRedirect("admin-dashboard");}catch(Exception e){getServletContext().log(getServletConfig().getInitParameter("module")+" failed",e);Flash.set(q,"error","Admin login failed. Check database setup.");s.sendRedirect("admin-login.jsp");}}}